223:
SELECT c."atom_id", c."atom_id2"
FROM "connected" c
WHERE c."bond_id" = 'TR000_2_5';

319:
SELECT COUNT(DISTINCT c."atom_id") AS element_count
FROM "connected" c
WHERE c."bond_id" = 'TR001_3_4';

416:
SELECT

    (COUNT(*) FILTER (
        WHERE (c."power" IS NULL OR c."power" = '*')
          AND fd."language" = 'French'
    )::numeric
    / NULLIF(COUNT(*) FILTER (
        WHERE (c."power" IS NULL OR c."power" = '*')
    ), 0)) * 100 AS percentage
FROM cards c
JOIN foreign_data fd ON fd."uuid" = c."uuid";

661:
SELECT "u"."age"
FROM "users" AS "u"
WHERE "u"."reputation" = (
    SELECT MAX("reputation") FROM "users"
)
LIMIT 1;

588:
SELECT COUNT(*) AS total_comments
FROM "comments" c
WHERE c."userid" = 13;

572:
SELECT "p"."viewcount"
FROM "posts" AS "p"
WHERE "p"."title" = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

745:
SELECT p."id"
FROM "publisher" AS p
WHERE p."publisher_name" = 'Star Trek';

803:
SELECT sp."id"
FROM "superpower" AS sp
WHERE sp."power_name" = 'cryokinesis';

747:
SELECT COUNT(*) AS superheroes_without_full_name
FROM "superhero" AS s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(*) AS president_count
FROM "member" m
WHERE LOWER(TRIM(m."position")) = 'president';

1365:
SELECT e."expense_description"
FROM "expense" e
JOIN "budget" b ON e."link_to_budget" = b."budget_id"
WHERE b."remaining" = (
    SELECT MIN("remaining") FROM "budget"
);
